ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS variants jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS benefits_bn text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS benefits_en text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS usage_bn text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS usage_en text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS caution_bn text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS caution_en text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS source_url text NOT NULL DEFAULT '';

INSERT INTO public.products (name_bn,name_en,price,old_price,image,category,desc_bn,desc_en,active,sort,variants,benefits_bn,benefits_en,usage_bn,usage_en,caution_bn,caution_en,source_url)
VALUES
('মেথিমিক্স','Methimix',590,NULL,'https://ecorybd.com/wp-content/uploads/2023/08/MM-300x300.jpg','stomach','আমলকি, হরিতকি, বহেড়া, মেথিসহ নির্বাচিত ভেষজ উপাদানের ১০০ গ্রাম মিশ্রণ; এক ফাইল প্রায় এক মাসের কোর্স।','A 100g blend of selected botanicals including amla, haritaki, bahera and fenugreek; one container is approximately a one-month course.',true,10,'[{"id":"methi-1","label_bn":"১ ফাইল · ১০০ গ্রাম","label_en":"1 jar · 100g","price":590,"image":"https://ecorybd.com/wp-content/uploads/2023/08/MM-300x300.jpg"},{"id":"methi-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1000,"image":"https://ecorybd.com/wp-content/uploads/2023/08/MM-2.jpg"},{"id":"methi-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":1500,"image":"https://ecorybd.com/wp-content/uploads/2023/08/MM-3.jpg"}]','গ্যাস্ট্রিকের অস্বস্তি, টক ঢেকুর, ক্ষুধামন্দা ও বদহজমে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described on the website as supporting gastric comfort, appetite and digestion.','রাতে খাবারের পর আধা গ্লাস পানিতে এক চামচ মিশিয়ে পান করুন।','Mix one spoon in half a glass of water after dinner.','এটি খাদ্য সম্পূরক, ওষুধ নয়। গর্ভবতী, স্তন্যদানকারী, শিশু বা নিয়মিত ওষুধ সেবনকারী চিকিৎসকের পরামর্শ নিন।','This is a food supplement, not medicine. Consult a doctor if pregnant, breastfeeding, underage or taking regular medication.','https://ecorybd.com/product/methimix/'),
('কোষ্ঠকেয়ার','Kostocare',590,NULL,'https://ecorybd.com/wp-content/uploads/2023/08/KC-300x300.jpg','stomach','কোষ্ঠকাঠিন্যের দৈনন্দিন যত্নে তৈরি প্রাকৃতিক ভেষজ মিশ্রণ।','A natural botanical blend for everyday digestive care.',true,11,'[{"id":"kosto-1","label_bn":"১ ফাইল","label_en":"1 jar","price":590},{"id":"kosto-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1000},{"id":"kosto-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":1500},{"id":"kosto-combo","label_bn":"পাইলস কম্বো","label_en":"Piles combo","price":1290}]','নিয়মিত মলত্যাগ, পেটের স্বস্তি এবং ক্লান্তি কমাতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described on the website as supporting regularity, digestive comfort and energy.','','','ফল ব্যক্তি ভেদে ভিন্ন হতে পারে। দীর্ঘস্থায়ী সমস্যায় চিকিৎসকের পরামর্শ নিন।','Results vary. Consult a doctor for persistent symptoms.','https://ecorybd.com/product/kostocare/'),
('থানকুয়ান','Thankuan',590,NULL,'https://ecorybd.com/wp-content/uploads/2023/08/TK-2-300x300.jpg','stomach','থানকুনি, বেল, জোয়ান, আদা ও দারুচিনিসহ ভেষজ উপাদানের মিশ্রণ।','A botanical blend with thankuni, bael, ajwain, ginger and cinnamon.',true,12,'[{"id":"thank-1","label_bn":"১ ফাইল · ১০০ গ্রাম","label_en":"1 jar · 100g","price":590},{"id":"thank-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1000},{"id":"thank-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":1500}]','হজম শক্তি, ক্ষুধা ও পেটের স্বস্তিতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting digestion, appetite and gut comfort.','সকালে খাবারের পর আধা গ্লাস কুসুম গরম পানিতে এক চামচ মিশিয়ে পান করুন।','Mix one spoon in half a glass of warm water after breakfast.','গুরুতর বা দীর্ঘস্থায়ী পেটের সমস্যায় চিকিৎসকের পরামর্শ নিন।','Consult a doctor for serious or persistent digestive symptoms.','https://ecorybd.com/product/thankuan/'),
('সীডমিক্স','Seedmix',590,NULL,'https://ecorybd.com/wp-content/uploads/2023/12/SM-2-300x300.jpg','nutrition','বিভিন্ন পুষ্টিকর বীজের প্রাকৃতিক মিশ্রণ।','A natural blend of nutritious seeds.',true,13,'[{"id":"seed-1","label_bn":"১ প্যাক","label_en":"1 pack","price":590},{"id":"seed-2","label_bn":"২ প্যাক","label_en":"2 packs","price":1200},{"id":"seed-3","label_bn":"৩ প্যাক","label_en":"3 packs","price":1800}]','হজম, দৈনন্দিন পুষ্টি ও রোগ প্রতিরোধ ক্ষমতায় সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting digestion, daily nutrition and immunity.','','','পরিমিত পরিমাণে গ্রহণ করুন; অ্যালার্জি থাকলে উপাদান যাচাই করুন।','Consume in moderation and check ingredients if you have allergies.','https://ecorybd.com/product/seed-mix/'),
('সীডমিক্স পাউডার','Seedmix Powder',590,NULL,'https://ecorybd.com/wp-content/uploads/2025/10/SMP-21-300x300.jpg','stomach','সহজে গ্রহণযোগ্য পাউডার আকারে পুষ্টিকর বীজের মিশ্রণ।','A convenient powdered blend of nutritious seeds.',true,14,'[{"id":"seedp-1","label_bn":"১ প্যাক","label_en":"1 pack","price":590},{"id":"seedp-2","label_bn":"২ প্যাক","label_en":"2 packs","price":990}]','হজম, পেটের স্বস্তি ও ইমিউনিটি সহায়তায় ওয়েবসাইটে বর্ণিত।','Described as supporting digestion, gut comfort and immunity.','','','পরিমিত গ্রহণ করুন এবং অ্যালার্জি থাকলে উপাদান যাচাই করুন।','Consume in moderation and check ingredients if allergic.','https://ecorybd.com/product/seedmix-pawder/'),
('অর্জুন মিক্স পাউডার','Arjun Mix Powder',590,NULL,'https://ecorybd.com/wp-content/uploads/2025/12/AM-2-300x300.jpg','heart','নির্বাচিত অর্জুন ছালের গুঁড়া দিয়ে তৈরি হার্ট-কেয়ার মিশ্রণ।','A heart-care blend made with selected arjun bark powder.',true,15,'[{"id":"arjun-1","label_bn":"১ ফাইল","label_en":"1 jar","price":590},{"id":"arjun-2","label_bn":"২ ফাইল","label_en":"2 jars","price":990},{"id":"arjun-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":1350}]','হার্টের স্বাভাবিক কার্যক্রম, রক্তপ্রবাহ ও রক্তচাপ বজায় রাখতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting normal heart function, circulation and blood pressure.','','','হৃদরোগ বা রক্তচাপের ওষুধ চললে চিকিৎসকের পরামর্শ ছাড়া গ্রহণ করবেন না।','Do not take without medical advice if using heart or blood-pressure medicine.','https://ecorybd.com/product/arjun-mix-powder/'),
('সুগারভেষ','Sugervez',990,NULL,'https://ecorybd.com/wp-content/uploads/2024/09/SV-2-scaled.jpg','heart','রক্তে শর্করা ব্যবস্থাপনায় সহায়ক ভেষজ ফুড সাপ্লিমেন্ট।','A botanical food supplement intended to support blood sugar management.',true,16,'[{"id":"sugar-1","label_bn":"১ ফাইল","label_en":"1 jar","price":990},{"id":"sugar-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1900},{"id":"sugar-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":2800}]','অ্যান্টিঅক্সিডেন্ট ও স্বাভাবিক রক্তে শর্করা ব্যবস্থাপনায় সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as providing antioxidant and blood-sugar management support.','','','ডায়াবেটিসের ওষুধ বন্ধ বা পরিবর্তন করবেন না; চিকিৎসকের পরামর্শ নিন।','Do not stop or change diabetes medication; consult your doctor.','https://ecorybd.com/product/sugervez/'),
('বড়ই পাতা মিক্স','Barai Pata Mix',590,NULL,'https://ecorybd.com/wp-content/uploads/2025/12/BPM-1-300x300.jpg','lungs','শ্বাসযন্ত্রের দৈনন্দিন যত্নে প্রাকৃতিক উপাদানের মিশ্রণ।','A natural blend for everyday respiratory care.',true,17,'[{"id":"barai-1","label_bn":"১ ফাইল","label_en":"1 jar","price":590},{"id":"barai-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1000},{"id":"barai-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":1500}]','শ্বাসনালি পরিষ্কার রাখা ও স্বাভাবিক শ্বাসপ্রশ্বাসে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting clear airways and normal breathing.','','','হঠাৎ শ্বাসকষ্ট হলে জরুরি চিকিৎসা নিন; এটি ইনহেলারের বিকল্প নয়।','Seek urgent care for sudden breathing difficulty; this is not an inhaler substitute.','https://ecorybd.com/product/barai-pata-mix/'),
('নিমরো','Nimro',990,NULL,'https://ecorybd.com/wp-content/uploads/2023/10/NM-2-300x300.jpg','lungs','অ্যালার্জি-প্রবণতার দৈনন্দিন যত্নে ভেষজ মিশ্রণ।','A botanical blend for daily allergy-prone wellness care.',true,18,'[{"id":"nimro-1","label_bn":"১ ফাইল","label_en":"1 jar","price":990},{"id":"nimro-2","label_bn":"২ ফাইল","label_en":"2 jars","price":1900},{"id":"nimro-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":2800}]','অ্যালার্জিজনিত চুলকানি ও অস্বস্তি কমাতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting comfort from allergy-related itching.','','','তীব্র অ্যালার্জি বা শ্বাসকষ্টে জরুরি চিকিৎসা নিন।','Seek urgent medical care for severe allergy or breathing difficulty.','https://ecorybd.com/product/nimro/'),
('অশ্বশক্তি','Awshashakti',490,NULL,'https://ecorybd.com/wp-content/uploads/2024/09/AS-2-300x300.jpg','energy','দৈনন্দিন শারীরিক শক্তি ও প্রাণশক্তির জন্য ভেষজ ফুড সাপ্লিমেন্ট।','A botanical food supplement for everyday strength and vitality.',true,19,'[{"id":"awsha-trial","label_bn":"ট্রায়াল","label_en":"Trial","price":490},{"id":"awsha-1","label_bn":"১ ফাইল","label_en":"1 jar","price":1290},{"id":"awsha-2","label_bn":"২ ফাইল","label_en":"2 jars","price":2200},{"id":"awsha-3","label_bn":"৩ ফাইল","label_en":"3 jars","price":3000}]','শারীরিক দুর্বলতা ও কর্মশক্তিতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting physical vitality and stamina.','','','নির্দিষ্ট স্বাস্থ্যসমস্যা বা ওষুধ থাকলে চিকিৎসকের পরামর্শ নিন।','Consult a doctor if you have a medical condition or take medication.','https://ecorybd.com/product/awshashakti/'),
('অশ্বগন্ধা পাউডার','Ashwagandha Powder',590,NULL,'https://ecorybd.com/wp-content/uploads/2024/04/AS-2-300x300.jpg','energy','নির্বাচিত অশ্বগন্ধা থেকে তৈরি প্রাকৃতিক পাউডার।','Natural powder made from selected ashwagandha.',true,20,'[{"id":"ashwa-200","label_bn":"২০০ গ্রাম","label_en":"200g","price":590},{"id":"ashwa-400","label_bn":"৪০০ গ্রাম","label_en":"400g","price":1000}]','ঘুম, মানসিক চাপ ও দৈনন্দিন প্রাণশক্তিতে সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting sleep, stress management and daily vitality.','','','গর্ভাবস্থা, থাইরয়েড সমস্যা বা নিয়মিত ওষুধ সেবনে চিকিৎসকের পরামর্শ নিন।','Consult a doctor during pregnancy, with thyroid conditions, or when taking medicine.','https://ecorybd.com/product/ashwagandha/'),
('আরাবিয়ান এনার্জি বুস্টার','Arabian Energy Booster',890,990,'https://ecorybd.com/wp-content/uploads/2025/10/AAB-2-300x300.jpg','energy','শরীর ও মনের শক্তির জন্য প্রাকৃতিক উপাদানের মিশ্রণ।','A natural blend designed for physical and mental energy.',true,21,'[{"id":"arabian-1","label_bn":"১ প্যাক","label_en":"1 pack","price":890}]','কর্মশক্তি, স্ট্যামিনা, ফোকাস ও ক্লান্তি ব্যবস্থাপনায় সহায়ক হিসেবে ওয়েবসাইটে বর্ণিত।','Described as supporting stamina, focus and fatigue management.','','','পরিমিত গ্রহণ করুন; স্বাস্থ্যসমস্যা থাকলে চিকিৎসকের পরামর্শ নিন।','Consume in moderation; consult a doctor for existing health conditions.','https://ecorybd.com/product/arabian-energy-booster/'),
('বিটরুট পাউডার','Beetroot Powder',890,NULL,'https://ecorybd.com/wp-content/uploads/2024/05/BT-2-300x300.jpg','nutrition','বাছাই করা বিটরুট থেকে তৈরি সহজে ব্যবহারযোগ্য প্রাকৃতিক পাউডার।','A convenient natural powder made from selected beetroot.',true,22,'[{"id":"beet-1","label_bn":"১ প্যাক","label_en":"1 pack","price":890},{"id":"beet-2","label_bn":"২ প্যাক","label_en":"2 packs","price":1690}]','দৈনন্দিন পুষ্টি, রক্তপ্রবাহ ও অ্যান্টিঅক্সিডেন্ট সহায়তায় ওয়েবসাইটে বর্ণিত।','Described as supporting daily nutrition, circulation and antioxidants.','','','লো ব্লাড প্রেসার বা কিডনি সমস্যায় চিকিৎসকের পরামর্শ নিন।','Consult a doctor for low blood pressure or kidney conditions.','https://ecorybd.com/product/beetroot-powder/'),
